# Real-evidence tasks (non-Upworthy). Each item: dict; build.py fills defaults.
def pick(mod, prompt, a, b, ans, ev, metric, src, expl, pr, ctx=None, **kw):
    d=dict(type="pick", module=mod, prompt=prompt, options=[{"text":a},{"text":b}], answer=ans, evidence_type=ev, metric=metric, source=src, explanation=expl, principles=pr)
    if ctx: d["context"]=ctx
    d.update(kw); return d

